// ignore_for_file: unused_element, unnecessary_cast

import 'logging.dart';

/// Result data returned by run.
class RunResult {
  /// If the previous command's stdout and stderr (as generated by the prior create/update) is
  /// injected into the environment of the next run as PULUMI_COMMAND_STDOUT and PULUMI_COMMAND_STDERR.
  /// Defaults to true.
  final bool? addPreviousOutputInEnv;
  /// An archive asset containing files found after running the command.
  final dynamic archive;
  /// A list of path globs to return as a single archive asset after the command completes.
  ///
  /// When specifying glob patterns the following rules apply:
  /// - We only include files not directories for assets and archives.
  /// - Path separators are `/` on all platforms - including Windows.
  /// - Patterns starting with `!` are 'exclude' rules.
  /// - Rules are evaluated in order, so exclude rules should be after inclusion rules.
  /// - `*` matches anything except `/`
  /// - `**` matches anything, _including_ `/`
  /// - All returned paths are relative to the working directory (without leading `./`) e.g. `file.text` or `subfolder/file.txt`.
  /// - For full details of the globbing syntax, see [github.com/gobwas/glob](https://github.com/gobwas/glob)
  ///
  /// #### Example
  ///
  /// Given the rules:
  /// ```yaml
  /// - "assets/**"
  /// - "src/**.js"
  /// - "!**secret.*"
  /// ```
  ///
  /// When evaluating against this folder:
  ///
  /// ```yaml
  /// - assets/
  ///   - logos/
  ///     - logo.svg
  /// - src/
  ///   - index.js
  ///   - secret.js
  /// ```
  ///
  /// The following paths will be returned:
  ///
  /// ```yaml
  /// - assets/logos/logo.svg
  /// - src/index.js
  /// ```
  final List<String>? archivePaths;
  /// A list of path globs to read after the command completes.
  ///
  /// When specifying glob patterns the following rules apply:
  /// - We only include files not directories for assets and archives.
  /// - Path separators are `/` on all platforms - including Windows.
  /// - Patterns starting with `!` are 'exclude' rules.
  /// - Rules are evaluated in order, so exclude rules should be after inclusion rules.
  /// - `*` matches anything except `/`
  /// - `**` matches anything, _including_ `/`
  /// - All returned paths are relative to the working directory (without leading `./`) e.g. `file.text` or `subfolder/file.txt`.
  /// - For full details of the globbing syntax, see [github.com/gobwas/glob](https://github.com/gobwas/glob)
  ///
  /// #### Example
  ///
  /// Given the rules:
  /// ```yaml
  /// - "assets/**"
  /// - "src/**.js"
  /// - "!**secret.*"
  /// ```
  ///
  /// When evaluating against this folder:
  ///
  /// ```yaml
  /// - assets/
  ///   - logos/
  ///     - logo.svg
  /// - src/
  ///   - index.js
  ///   - secret.js
  /// ```
  ///
  /// The following paths will be returned:
  ///
  /// ```yaml
  /// - assets/logos/logo.svg
  /// - src/index.js
  /// ```
  final List<String>? assetPaths;
  /// A map of assets found after running the command.
  /// The key is the relative path from the command dir
  final Map<String, dynamic>? assets;
  /// The command to run.
  final String command;
  /// The directory from which to run the command from. If `dir` does not exist, then
  /// `Command` will fail.
  final String? dir;
  /// Additional environment variables available to the command's process.
  final Map<String, String>? environment;
  /// The program and arguments to run the command.
  /// On Linux and macOS, defaults to: `["/bin/sh", "-c"]`. On Windows, defaults to: `["cmd", "/C"]`
  final List<String>? interpreter;
  /// If the command's stdout and stderr should be logged. This doesn't affect the capturing of
  /// stdout and stderr as outputs. If there might be secrets in the output, you can disable logging here and mark the
  /// outputs as secret via 'additionalSecretOutputs'. Defaults to logging both stdout and stderr.
  final Logging? logging;
  /// The standard error of the command's process
  final String stderr;
  /// Pass a string to the command's process as standard in
  final String? stdin;
  /// The standard output of the command's process
  final String stdout;

  /// Creates a new [RunResult].
  /// [addPreviousOutputInEnv] If the previous command's stdout and stderr (as generated by the prior create/update) is
  /// [archive] An archive asset containing files found after running the command.
  /// [archivePaths] A list of path globs to return as a single archive asset after the command completes.
  /// [assetPaths] A list of path globs to read after the command completes.
  /// [assets] A map of assets found after running the command.
  /// [command] The command to run.
  /// [dir] The directory from which to run the command from. If `dir` does not exist, then
  /// [environment] Additional environment variables available to the command's process.
  /// [interpreter] The program and arguments to run the command.
  /// [logging] If the command's stdout and stderr should be logged. This doesn't affect the capturing of
  /// [stderr] The standard error of the command's process
  /// [stdin] Pass a string to the command's process as standard in
  /// [stdout] The standard output of the command's process
  const RunResult({
    this.addPreviousOutputInEnv,
    this.archive,
    this.archivePaths,
    this.assetPaths,
    this.assets,
    required this.command,
    this.dir,
    this.environment,
    this.interpreter,
    this.logging,
    required this.stderr,
    this.stdin,
    required this.stdout,
  });

  Map<String, dynamic> toMap() {
    return <String, dynamic>{
      'addPreviousOutputInEnv': ?addPreviousOutputInEnv,
      'archive': ?archive,
      'archivePaths': ?archivePaths,
      'assetPaths': ?assetPaths,
      'assets': ?assets,
      'command': command,
      'dir': ?dir,
      'environment': ?environment,
      'interpreter': ?interpreter,
      'logging': ?logging?.wireValue,
      'stderr': stderr,
      'stdin': ?stdin,
      'stdout': stdout,
    };
  }

  factory RunResult.fromMap(Map<String, dynamic> map) {
    return RunResult(
      addPreviousOutputInEnv: (() { final guardedValue = map['addPreviousOutputInEnv']; if (guardedValue == null) return null; return guardedValue as bool; })(),
      archive: (() { final guardedValue = map['archive']; if (guardedValue == null) return null; return guardedValue; })(),
      archivePaths: (() { final guardedValue = map['archivePaths']; if (guardedValue == null) return null; return (guardedValue as List).cast<String>(); })(),
      assetPaths: (() { final guardedValue = map['assetPaths']; if (guardedValue == null) return null; return (guardedValue as List).cast<String>(); })(),
      assets: (() { final guardedValue = map['assets']; if (guardedValue == null) return null; return (guardedValue as Map).cast<String, dynamic>(); })(),
      command: map['command'] as String,
      dir: (() { final guardedValue = map['dir']; if (guardedValue == null) return null; return guardedValue as String; })(),
      environment: (() { final guardedValue = map['environment']; if (guardedValue == null) return null; return (guardedValue as Map).cast<String, String>(); })(),
      interpreter: (() { final guardedValue = map['interpreter']; if (guardedValue == null) return null; return (guardedValue as List).cast<String>(); })(),
      logging: (() { final guardedValue = map['logging']; if (guardedValue == null) return null; return Logging.fromValue(guardedValue as String); })(),
      stderr: map['stderr'] as String,
      stdin: (() { final guardedValue = map['stdin']; if (guardedValue == null) return null; return guardedValue as String; })(),
      stdout: map['stdout'] as String,
    );
  }
}
